  //  drains every slot each cycle.  A free-running pointer on each side: a
  //  checker that overruns an undrained mailbox loses the oldest entry, which
  //  is recorded in evt_overflow rather than silently dropped.
  step4_evt_t evt [EVT_SLOTS];
  int unsigned evt_w = 0;
  int unsigned evt_r = 0;
  int unsigned evt_overflow = 0;

